define function "CRD Matrix"(requestItem Choice<FHIR.NutritionOrder, FHIR.ServiceRequest, FHIR.DeviceRequest, FHIR.MedicationRequest, FHIR.VisionPrescription, FHIR.Appointment>):
  {
    "CRD-7": { 
      "ID": 'CRD-7',
      "Covered": 'covered', 
      "PriorAuthNeeded": 'no-auth', 
      "DetailCode": 'no-auth', 
      "DetailText": 'Prior Authorization Not Required', 
      "DetailQualification": 'Order is covered. No prior auth is required for ' + "Service Request Item Code"(requestItem).display + '.',
      "DetailDebugging": 'Not yet implemented.',
      "DetailValue": 'info'
    }
  }
